/* Commissioned balcony work: authorization -> three checks -> physical opening -> pay.
   IDs retain the old event namespace. No time-check may mutate a sash early. */
static float bonus_duration(void);static float bonus_width(void);static float bonus_center(void);
static int work_valid(int id){if(id>=3000&&id<3096)return ((id-3000)%24)/2<high_floors180((id-3000)/24);return (id>=0&&id<NW)||(id>=1000&&id<1000+NH*24)||(id>=200&&id<800&&(id-200)%40<32);}
static int work_floor(int id){return id>=3000?((id-3000)%24)/2:id>=1000?1+((id-1000)%24)/6:id>=200?((id-200)%40%16)/4:0;}
static int work_home(int id){return id>=0&&id<3;}
static void work_point(int id,float*x,float*y,float*z){*x=*z=0;*y=-999;if(!work_valid(id))return;if(id>=3000){int n=(id-3000)/24,k=(id-3000)%24;*x=cityBlockX[n]+(k%2?1:-1)*4.8f;*y=(k/2)*3+1.8f;*z=cityBlockZ[n]+5.23f;return;}if(id<NW){window_handle_pos(id,x,y,z);return;}if(id>=1000){int h=(id-1000)/24,k=(id-1000)%24,f=1+k/6,side=(k%6)/3;*x=hx[h]+window_a180(side,k%3);*y=f*3+1.75f;*z=hz[h]+(side?4.48f:-4.48f);return;}int p=(id-200)/40,k=(id-200)%40,w=k/16,f=k%16/4,c=k%4;*x=panel_origin_x(p)+(w?7:-7)+(c<2?-1:1)*(c%2?6:4);*y=f*3+1.7f;*z=panel_origin_z(p)+7.85f;}
static int work_open(int id){if(!work_valid(id))return 0;if(id>=3000)return !!(g.highWindows180[(id-3000)/24]&(1u<<((id-3000)%24)));if(id<NW)return WIN(id).handle>0;if(id>=1000)return !!(g.residence[(id-1000)/24].windows&(1ull<<((id-1000)%24)));int p=(id-200)/40,k=(id-200)%40;return !!((p?g.district[p].windows:g.panelWindowOpen)&(1ull<<k));}
static void work_set(int id,int value){if(!work_valid(id))return;if(id>=3000){unsigned*b=&g.highWindows180[(id-3000)/24],bit=1u<<((id-3000)%24);if(value)*b|=bit;else *b&=~bit;return;}if(id<NW){WIN(id).handle=value;WIN(id).mode=1;if(!value)WIN(id).angle=0;return;}unsigned long long*bits;if(id>=1000){bits=&g.residence[(id-1000)/24].windows;id=(id-1000)%24;}else{int p=(id-200)/40;bits=p?&g.district[p].windows:&g.panelWindowOpen;id=(id-200)%40;}if(value)*bits|=1ull<<id;else *bits&=~(1ull<<id);}
static int work_access(int id){if(!work_valid(id))return 0;if(id<NW)return window_access(id);float x,y,z;work_point(id,&x,&y,&z);if(ab(g.playerY-work_floor(id)*3)>.22f||dst(g.x,g.z,x,z)>2.65f)return 0;if(id>=3000){int n=(id-3000)/24;return high_at180(g.x,g.z)==n&&ab(g.x-cityBlockX[n])>1.9f&&g.z>cityBlockZ[n]+2.0f&&g.z<cityBlockZ[n]+6.8f;}if(id>=1000){int h=(id-1000)/24;return ab(g.x-hx[h])<4.65f&&ab(g.z-hz[h])<4.12f;}int p=(id-200)/40;float ox=panel_origin_x(p),oz=panel_origin_z(p);return ab(g.x-ox)<15.6f&&g.z>oz+4.5f&&g.z<oz+7.6f;}
static void work_assign(int j,int h,int f){if(j<0||j>=NJ||h<1||h>=NH)return;Job*q=&g.jobs[j];q->house=h;q->type=0;q->mode=1;q->count=1;q->done=q->mask=0;q->pay=market_price(220+f*30+(int)mn(g.rank,8)*12);q->deadline=g.absolute+24;q->apprentice=-1;g.workTarget[j]=f?1000+h*24+(f-1)*6+4:h*3+1;}
static void work_migrate(void){if(g.version<14||g.workRevision!=1){for(int j=0;j<NJ;j++){int accepted=g.jobs[j].apprentice==-2;work_assign(j,g.jobs[j].house,j==0?0:1+j);if(accepted)g.jobs[j].apprentice=-2;}g.workRevision=1;g.winter=1;g.hudOpacity=1;g.options[9]=0;g.options[10]=0;}for(int j=0;j<NJ;j++){int id=g.workTarget[j],h=g.jobs[j].house;if(id>=3000&&work_valid(id))continue;if(!(id==h*3+1||(id>=1000+h*24&&id<1000+(h+1)*24&&((id-1000)%6)==4))){int accepted=g.jobs[j].apprentice==-2;work_assign(j,h,j?j:0);if(accepted)g.jobs[j].apprentice=-2;}}}
static int work_job(int id){for(int j=0;j<NJ;j++)if(job_accepted(j)&&g.workTarget[j]==id&&g.jobs[j].done<g.jobs[j].count&&g.jobs[j].deadline>=g.absolute)return j;return -1;}
static void work_cancel(void){if(workPending>=0){workPending=-1;workHits=0;bonusActive=0;bonusClock=0;}}
static void work_say(const char*message){say(message);workNoticeUntil=realTime+3;}
static const char*work_hint(int id){return work_open(id)?"E / ЛКМ — закрыть створку":work_home(id)?"E / ЛКМ — открыть домашнее окно":workPending==id?"ЛКМ / ПРОБЕЛ — три точных движения":work_job(id)>=0?"E / ЛКМ — открыть заказанный балкон":"Нет принятого заказа на эту створку";}
static int work_interact(int id){if(!work_access(id))return 0;if(workPending>=0){if(workPending==id)return 1;work_cancel();}bonusActive=0;if(work_open(id)){work_set(id,0);audio(13);event_log("window_closed",id);return 1;}if(work_home(id)){work_set(id,1);audio(12);event_log("open_window",id);work_say("Домашнее окно открыто — здесь проверка не нужна.");return 1;}if(work_job(id)<0){work_say("На эту створку нет принятого заказа. Проверь адрес и этаж.");return 1;}workPending=id;workHits=0;workCenter=.12f+rnd()*.76f;bonusId=id;bonusClock=0;bonusActive=1;event_log("skill_check_started",id);work_say("Три точных движения. Промах — створка останется закрыта.");return 1;}
static void work_check_tick(float dt){int id=workPending,j=work_job(id);if(id<0)return;if(j<0||!work_access(id)){work_cancel();work_say("Работа прервана: отойди нельзя, заказ должен оставаться активным.");return;}bonusClock+=dt;float phase=bonusClock/bonus_duration(),distance=ab(phase-workCenter);int answer=bonusClock>.08f&&(pressed[32]||(autoChecks&&distance<bonus_width()*.22f));if(!answer&&phase<=1)return;int hit=answer&&distance<=bonus_width()*.5f;bonusChecks++;qteCount++;qteSuccess+=hit;eventValue=hit;event_log("skill_check_result",id);if(!hit){work_cancel();audio(6);work_say("Промах. Балкон закрыт, оплаты нет. Начни заново с ручки.");return;}workHits++;audio(5);if(workHits<3){bonusClock=0;workCenter=.12f+rnd()*.76f;event_log("skill_check_started",id);return;}work_cancel();if(work_job(id)!=j||!work_access(id)||work_open(id))return;work_set(id,1);audio(12);event_log("open_window",id);g.jobs[j].done=1;g.jobs[j].mask=1;skillLevel+=.8f;paid_job(j,-1);workNoticeUntil=realTime+5;save_game();}

/* Own dialogue frame, bounded scrollback, real work-offer branch (not a screenshot). */
typedef struct{int player;char text[640];} DialogEntry;
static DialogEntry dialogLog[32];static int dialogCount=0,dialogOwner=-1,dialogScroll=0,dialogOffer=-1;
static void dialog_add(int player,const char*text){if(dialogCount==32){for(int i=1;i<32;i++)dialogLog[i-1]=dialogLog[i];dialogCount=31;}DialogEntry*e=&dialogLog[dialogCount++];e->player=player;SN(e->text,sizeof(e->text),"%s",text);dialogScroll=0;}
static void dialog_begin(int n){dialogOwner=n;dialogCount=dialogScroll=0;dialogOffer=-1;dialog_add(0,"Здравствуй. Ты по балконам? Проходи, слушаю.");}
static void dialog_ensure(void){if(dialogOwner!=dialogNPC||!dialogCount)dialog_begin(dialogNPC);}
static void dialog_choose(int topic){dialog_ensure();if(dialogNPC>=NN){dialog_local200(topic);return;}if(topic==10||topic==11){dialogScroll=(int)clamp(dialogScroll+(topic==10?3:-3),0,380);return;}dialogTopic=topic;char answer[640];if(topic==3){dialog_add(1,"Берусь за этот балкон. Назови адрес и этаж.");if(dialogOffer>=0&&dialogOffer<NJ){accept_job(dialogOffer);SN(answer,sizeof(answer),"Договорились. Дом %d, этаж %d, центральная створка балкона со двора. Сначала ручка, потом замок, потом створка. Только после трёх точных движений она откроется. Оплата — через кассу.",g.jobs[dialogOffer].house+1,work_floor(g.workTarget[dialogOffer])+1);dialog_add(0,answer);dialogOffer=-1;}else dialog_add(0,"Сначала обсудим заявку — чужие окна просто так не трогают.");return;}
 dialog_add(1,topic==0?"Как дела?":topic==1?"Нужен профессиональный открывальщик балкона?":"Что нового во дворе?");
 if(topic==1&&!npc_child(dialogNPC)){int h=PERSON(dialogNPC).home;dialogOffer=-1;if(h>0){for(int j=0;j<NJ;j++)if(g.jobs[j].house==h)dialogOffer=j;if(dialogOffer<0)for(int j=0;j<NJ;j++)if(!job_accepted(j)){dialogOffer=j;work_assign(j,h,1+dialogNPC%4);break;}}if(dialogOffer>=0){Job*q=&g.jobs[dialogOffer];SN(answer,sizeof(answer),"Да. Дом %d, этаж %d. Центральная створка балкона со двора заклинила. За работу %d рублей. Остальные окна не трогай. Возьмёшься?",q->house+1,work_floor(g.workTarget[dialogOffer])+1,q->pay);dialog_add(0,answer);return;}dialog_add(0,"У меня пока нет заявки. Загляни в записную книжку: там адрес, этаж и оплата по каждому вызову.");return;}
 dialog_add(0,dialogue_line(dialogNPC,topic));}

static const char*house_label190(int h){if(h>=NH&&h<NH+4){static const char*const s[4]={"Панельная, 25 / подъезд 1","Панельная, 26 / подъезд 1","Панельная, 27 / подъезд 2","Панельная, 28 / подъезд 2"};return s[h-NH];}return h>=0&&h<NH?names[h]:"Адрес не указан";}
static void work_assign190(int j,int n,int f,int side){if(j<0||j>=NJ||n<0||n>=4)return;f=(int)clamp(f,0,high_floors180(n)-1);Job*q=&g.jobs[j];q->house=NH+n;q->type=0;q->mode=1;q->count=1;q->done=q->mask=0;q->pay=market_price(270+f*24+(int)mn(g.rank,8)*12);q->deadline=g.absolute+30;q->apprentice=-1;g.workTarget[j]=3000+n*24+f*2+(side!=0);}
